test('renderInvoiceText shows voucher before total', () => {
  const r = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'LOGO-PACK', qty: 1 }],
  });
  assert.equal(r.ok, true);
  let invoice = r.value;

  const r2 = applyVoucher(invoice, { code: 'SAVE10', discountCents: 10000 });
  assert.equal(r2.ok, true);
  invoice = r2.value;

  const r3 = renderInvoiceText(invoice);
  assert.equal(r3.ok, true);
  const text = r3.value;
  const lines = text.split('\n');

  // Find the voucher and total lines
  const voucherLineIdx = lines.findIndex(l => l.startsWith('Voucher:'));
  const totalLineIdx = lines.findIndex(l => l.startsWith('Total:'));

  assert.ok(voucherLineIdx >= 0, 'voucher line should exist');
  assert.ok(totalLineIdx > voucherLineIdx, 'total line should come after voucher line');
  assert.ok(lines[voucherLineIdx].includes('€100.00'));
});

