2	import { getCustomer } from './customers.js';
3	import { formatEuros } from './money.js';
4	import { lineTotal, lineDiscount, lineVat, invoiceTotals } from './invoices.js';
5	import { balanceDue } from './payments.js';
6	
7	/**
8	 * Render an invoice as plain text for display to customers.
9	 * @param {{ number?: string, customerId: string, lines: Array<{ qty: number, name: string, unitPrice: number }> }} invoice
10	 * @returns {{ ok: true, value: string } | { ok: false, error: string }}
11	 */
12	export function renderInvoiceText(invoice) {
13	  // Get invoice number or DRAFT
14	  const invoiceNumber = invoice.number || 'DRAFT';
15	
16	  // Look up customer
17	  const customerResult = getCustomer(invoice.customerId);
18	  if (!customerResult.ok) return customerResult;
19	
20	  const customer = customerResult.value;
21	
22	  // Build output lines
23	  const lines = [invoiceNumber, customer.name];
24	
25	  // Add invoice lines
26	  for (const line of invoice.lines) {
27	    const unitPriceText = formatEuros(line.unitPrice);
28	    const lineTotalAmount = lineTotal(line);
29	    const lineTotalText = formatEuros(lineTotalAmount);
30	    let lineText = `${line.qty} ${line.name} ${unitPriceText} ${lineTotalText}`;
